import Foundation

/// Renders `docs/compat/matrix.md` from the results.
public enum CompatMatrix {
    public static func markdown(_ records: [CompatRecord]) -> String {
        let sorted = records.sorted {
            ($0.status.sortRank, $0.name.lowercased(), $0.appID) < ($1.status.sortRank, $1.name.lowercased(), $1.appID)
        }
        var lines = [
            "# Compatibility matrix",
            "",
            "Generated by `scripts/compat.sh` from `results.json`. Do not edit by hand.",
            "",
            "How the tests run: each app is installed from Flathub on an arm64 guest, launched through a headless stub,"
                + " and its frames are read back by the host. The guest renders on the CPU (pixman); there is no GPU"
                + " path, so GPU-accelerated drawing (OpenGL, Vulkan, WebGL) is not exercised. Input is injected"
                + " through the agent. `unknown` input means no new frame arrived within 2 seconds. Results are from the"
                + " developer's Mac; a `works` rating does not cover every feature of an app.",
            "",
            "## Summary",
            "",
        ]
        for status in CompatStatus.allCases.sorted(by: { $0.sortRank < $1.sortRank }) {
            lines.append("- \(status.title): \(records.filter { $0.status == status }.count)")
        }
        lines += [
            "",
            "## Results",
            "",
            "| Status | App | ID | Window | Renders | Input | Clean exit | Tested | Notes |",
            "| --- | --- | --- | --- | --- | --- | --- | --- | --- |",
        ]
        for record in sorted {
            let name = record.screenshot.map { "[\(record.name)](\($0))" } ?? record.name
            let row = [
                record.status.title,
                name,
                "`\(record.appID)`",
                record.checks.windowAppears.label,
                record.checks.renders.label,
                record.checks.inputWorks.label,
                record.checks.cleanExit.label,
                ISO8601DateFormatter().string(from: record.testedAt),
                cell(record.notes.first ?? ""),
            ]
            lines.append("| " + row.joined(separator: " | ") + " |")
        }
        return lines.joined(separator: "\n") + "\n"
    }

    private static func cell(_ text: String) -> String {
        let flat = text.replacingOccurrences(of: "|", with: "\\|").replacingOccurrences(of: "\n", with: " ")
        return flat.count > 160 ? String(flat.prefix(157)) + "..." : flat
    }
}

extension CheckOutcome {
    var label: String {
        switch self {
        case .pass: "yes"
        case .fail: "no"
        case .unknown: "unknown"
        case .skipped: "-"
        }
    }
}
